function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined && isInvalidLimit(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  const cursorError = validateBeforeCursor(message.before);
  if (cursorError) {
    return {valid: false, error: cursorError.error};
  }

  const listMessage: ListSessionsMessage = {
    type: 'list_sessions',
  };

  if (message.limit !== undefined) {
    listMessage.limit = message.limit as number;
  }

  if (message.before !== undefined) {
    const before = message.before as Record<string, unknown>;
    listMessage.before = {
      sessionId: before.sessionId as string,
      updatedAt: before.updatedAt as string | number,
    };
  }

  return {
    valid: true,
    data: listMessage,
  };
}

function isInvalidLimit(limit: unknown): boolean {
  return !Number.isInteger(limit) || (limit as number) < 0;
}

function validateBeforeCursor(before: unknown): {error: string} | null {
  if (before === undefined) {
    return null;
  }

  if (typeof before !== 'object' || before === null || Array.isArray(before)) {
